import { migrateV1, resolveThemeDocument } from "@opencode/theme/tui"

// A complete palette resolved by the real host library, including native RGBA
// leaves and color groups. Load only with the host's matching Core version.
export function resolvedHostTheme() {
  return resolveThemeDocument(migrateV1({
    theme: {
      primary: "#00cc00",
      secondary: "#00cccc",
      accent: "#cc00cc",
      error: "#ff0000",
      warning: "#ffff00",
      success: "#00ff00",
      info: "#00ffff",
      text: "#e0e0e0",
      textMuted: "#808080",
      background: "#101010",
      backgroundPanel: "#202020",
      backgroundElement: "#303030",
      border: "#606060",
      borderActive: "#707070",
      borderSubtle: "#404040",
      diffAdded: "#00ff00",
      diffRemoved: "#ff0000",
      diffContext: "#e0e0e0",
      diffHunkHeader: "#00ffff",
      diffHighlightAdded: "#008800",
      diffHighlightRemoved: "#880000",
      diffAddedBg: "#002200",
      diffRemovedBg: "#220000",
      diffContextBg: "#101010",
      diffLineNumber: "#808080",
      diffAddedLineNumberBg: "#003300",
      diffRemovedLineNumberBg: "#330000",
      markdownText: "#e0e0e0",
      markdownHeading: "#00ffff",
      markdownLink: "#00cccc",
      markdownLinkText: "#00cccc",
      markdownCode: "#00ff00",
      markdownBlockQuote: "#808080",
      markdownEmph: "#e0e0e0",
      markdownStrong: "#ffffff",
      markdownHorizontalRule: "#606060",
      markdownListItem: "#e0e0e0",
      markdownListEnumeration: "#00ffff",
      markdownImage: "#cc00cc",
      markdownImageText: "#cc00cc",
      markdownCodeBlock: "#00ff00",
      syntaxComment: "#808080",
      syntaxKeyword: "#cc00cc",
      syntaxFunction: "#00ffff",
      syntaxVariable: "#e0e0e0",
      syntaxString: "#00ff00",
      syntaxNumber: "#ffff00",
      syntaxType: "#00cccc",
      syntaxOperator: "#e0e0e0",
      syntaxPunctuation: "#808080",
    },
  }), "dark")
}
